func (c *Cache) isStale(tile Tile, now time.Time) bool {
	if tile.Generation != c.generation {
		return true
	}
	return now.Sub(tile.FetchedAt) > c.window
}

func (c *Cache) evict(now time.Time) int {
	removed := 0
	for _, tile := range c.tiles {
		if now.Sub(tile.FetchedAt) > c.window {
			c.drop(tile)
			removed++
		}
	}
	return removed
}

func (c *Cache) isStale(tile Tile, now time.Time) bool {
	if tile.Generation != c.generation {
		return true
	}
	return now.Sub(tile.FetchedAt) > c.window
}

func (c *Cache) prefetch(tiles []Tile, now time.Time) {
	for _, tile := range tiles {
		c.warm(tile)
	}
}
